import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

function createCapsuleShape(THREE, width, height, radius) {
  const shape = new THREE.Shape();
  const halfWidth = width * 0.5;
  const halfHeight = height * 0.5;
  const r = Math.min(radius, halfHeight, halfWidth);

  shape.moveTo(-halfWidth + r, -halfHeight);
  shape.lineTo(halfWidth - r, -halfHeight);
  shape.absarc(halfWidth - r, -halfHeight + r, r, -Math.PI * 0.5, 0);
  shape.lineTo(halfWidth, halfHeight - r);
  shape.absarc(halfWidth - r, halfHeight - r, r, 0, Math.PI * 0.5);
  shape.lineTo(-halfWidth + r, halfHeight);
  shape.absarc(-halfWidth + r, halfHeight - r, r, Math.PI * 0.5, Math.PI);
  shape.lineTo(-halfWidth, -halfHeight + r);
  shape.absarc(-halfWidth + r, -halfHeight + r, r, Math.PI, Math.PI * 1.5);
  shape.closePath();

  return shape;
}

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  root.name = config?.id ?? 'pricing-badge';

  const width = 1.3;
  const height = 0.34;
  const borderWidth = 0.035;

  const outerGeometry = new THREE.ShapeGeometry(
    createCapsuleShape(THREE, width, height, height * 0.5)
  );
  const innerGeometry = new THREE.ShapeGeometry(
    createCapsuleShape(
      THREE,
      width - borderWidth * 2,
      height - borderWidth * 2,
      (height - borderWidth * 2) * 0.5
    )
  );

  const edgeMaterial = new MeshBasicNodeMaterial({
    color: new THREE.Color('#ff2a38'),
  });

  const surfaceMaterial = new MeshBasicNodeMaterial({
    color: new THREE.Color('#16161d'),
  });

  const edge = new THREE.Mesh(outerGeometry, edgeMaterial);
  edge.name = 'accent-edge';
  edge.position.z = 0.006;

  const surface = new THREE.Mesh(innerGeometry, surfaceMaterial);
  surface.name = 'ceramic-grain-surface';
  surface.position.z = 0.012;

  root.add(edge, surface);

  let loadedTexture = null;
  let disposed = false;

  if (config?.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((texture) => {
        if (disposed) {
          texture.dispose();
          return;
        }

        loadedTexture = texture;
        surfaceMaterial.map = texture;
        surfaceMaterial.needsUpdate = true;
      })
      .catch(() => {});
  }

  const hoverIn = gsap.timeline({ paused: true });
  hoverIn.to(root.position, {
    y: 0.15,
    duration: 0.35,
    ease: 'power3.out',
  });

  const hoverOut = gsap.timeline({ paused: true });
  hoverOut.to(root.position, {
    y: 0,
    duration: 0.35,
    ease: 'power3.out',
  });

  const pressTimeline = gsap.timeline({ paused: true });
  pressTimeline
    .to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'power2.out',
    })
    .to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.32,
      ease: 'back.out(2.2)',
    });

  const focusColor = new THREE.Color('#ff2a38');
  const dimEdgeColor = new THREE.Color('#8f1722');

  root.userData.handlers = {
    hover: () => {
      hoverOut.pause();
      hoverIn.restart();
    },

    hoverout: () => {
      hoverIn.pause();
      hoverOut.restart();
    },

    click: () => {
      pressTimeline.restart();
      ctx.emit('hub-pricing.select', {
        nodeId: config?.id ?? 'pricing-badge',
      });
    },

    focus: () => {
      edgeMaterial.color.copy(focusColor);
      edgeMaterial.needsUpdate = true;
    },

    blur: () => {
      edgeMaterial.color.copy(dimEdgeColor);
      edgeMaterial.needsUpdate = true;
    },
  };

  root.userData.cleanup = () => {
    disposed = true;

    hoverIn.kill();
    hoverOut.kill();
    pressTimeline.kill();

    outerGeometry.dispose();
    innerGeometry.dispose();
    edgeMaterial.dispose();
    surfaceMaterial.dispose();

    if (loadedTexture) {
      loadedTexture.dispose();
      loadedTexture = null;
    }
  };

  return root;
}
